import numpy as np

W1 = W['W1']

def vec(r, c, ch):
    return W1[(r * 10 + c) * 5 + ch]

cells = [(r, c) for r in range(1, 9) for c in range(1, 9)]

for ch in [0, 1, 2, 3]:
    sims = {}
    for dr in range(-2, 3):
        for dc in range(-2, 3):
            cos_list = []
            for r, c in cells:
                r2, c2 = r + dr, c + dc
                if 1 <= r2 <= 8 and 1 <= c2 <= 8:
                    v4 = vec(r, c, 4)
                    vx = vec(r2, c2, ch)
                    denom = np.linalg.norm(v4) * np.linalg.norm(vx) + 1e-12
                    cos_list.append(np.dot(v4, vx) / denom)
            if cos_list:
                sims[(dr, dc)] = np.mean(cos_list)
    best_shift = max(sims, key=sims.get)
    print(f"CH4 vs CH{ch}: best shift {best_shift} sim {sims[best_shift]:.3f}; sim(0,0) {sims.get((0,0), float('nan')):.3f}")

# Also print top 5 shifts for CH1 to see the shape of the correlation peak
sims1 = {}
for dr in range(-2, 3):
    for dc in range(-2, 3):
        cos_list = []
        for r, c in cells:
            r2, c2 = r + dr, c + dc
            if 1 <= r2 <= 8 and 1 <= c2 <= 8:
                v4 = vec(r, c, 4)
                v1 = vec(r2, c2, 1)
                denom = np.linalg.norm(v4) * np.linalg.norm(v1) + 1e-12
                cos_list.append(np.dot(v4, v1) / denom)
        if cos_list:
            sims1[(dr, dc)] = np.mean(cos_list)
top = sorted(sims1.items(), key=lambda kv: kv[1], reverse=True)[:5]
print("Top CH4-CH1 shifts:", [(k, round(v, 3)) for k, v in top])
